import {
  pgTable,
  uuid,
  text,
  timestamp,
  jsonb,
  unique,
} from "drizzle-orm/pg-core";
import { tenants } from "./tenants";
import { users } from "./users";

export type AttestationCredentialResponse = {
  credentialId: string;
  confirmed: boolean;
  note?: string;
};

export type AttestationLockerResponse = {
  allocationId: string;
  keep: boolean;
  // Set when the member's own allocation had already ended by the time they
  // answered; recorded but never blocks the renewal.
  ignored?: "already_ended";
  // True when the member did not answer for this locker (older client) and
  // the renewal treated it as keep.
  implicit?: boolean;
};

export const attestationRequests = pgTable("attestation_requests", {
  id: uuid("id").primaryKey().defaultRandom(),
  tenantId: uuid("tenant_id")
    .notNull()
    .references(() => tenants.id),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id),
  season: text("season").notNull(),
  token: text("token").unique().notNull(),
  tokenExpiresAt: timestamp("token_expires_at", { withTimezone: true }).notNull(),
  status: text("status").notNull().default("pending"),
  credentialResponses: jsonb("credential_responses")
    .$type<AttestationCredentialResponse[]>(),
  // When set, the attestation is scoped to these credentials only (an admin
  // re-added a fob the member says they already hold and the member must
  // confirm it before the expiry update goes to the programmer). NULL is the
  // ordinary whole-membership renewal attestation.
  credentialIds: jsonb("credential_ids").$type<string[]>(),
  // Lockers module: the member's keep / release answers for any lockers they
  // held. NULL when the module was off or the member held none.
  lockerResponses: jsonb("locker_responses").$type<AttestationLockerResponse[]>(),
  completedAt: timestamp("completed_at", { withTimezone: true }),
  initiatedBy: uuid("initiated_by")
    .notNull()
    .references(() => users.id),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});
