"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";

export type AttestationPendingRowProps = {
  tenantSlug: string;
  attestation: {
    id: string;
    userId: string;
    season: string;
    tokenExpiresAt: string | null;
    memberFirstName: string | null;
    memberLastName: string | null;
    memberEmail: string | null;
  };
};

export function AttestationPendingRow({ tenantSlug, attestation }: AttestationPendingRowProps) {
  const router = useRouter();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [resent, setResent] = useState(false);

  async function resend() {
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/v1/t/${tenantSlug}/members/${attestation.userId}/resend-attestation`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ attestationId: attestation.id }),
        }
      );
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error ?? "Failed to resend");
      }
      setResent(true);
      setTimeout(() => router.refresh(), 1000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setSubmitting(false);
    }
  }

  const name = [attestation.memberFirstName, attestation.memberLastName]
    .filter(Boolean)
    .join(" ") || "Member";

  const expiresLabel = attestation.tokenExpiresAt
    ? new Date(attestation.tokenExpiresAt).toLocaleDateString("en-AU", {
        timeZone: "Australia/Melbourne",
        day: "numeric",
        month: "short",
        year: "numeric",
      })
    : null;

  return (
    <div className="flex items-center justify-between rounded-lg border border-blue-200 bg-white p-3 text-sm">
