          <Link
            href={`/t/${tenantSlug}/admin/members/${attestation.userId}`}
            className="font-medium hover:text-primary hover:underline"
          >
            {name}
          </Link>
          <span className="text-muted-foreground">{attestation.memberEmail}</span>
        </div>
        <p className="text-xs text-muted-foreground mt-0.5">
          Attestation pending for {attestation.season}
          {expiresLabel ? ` · token expires ${expiresLabel}` : ""}
        </p>
