"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export function RenewButton({
  tenantSlug,
  userId,
  seasons,
  currentSeason,
}: {
  tenantSlug: string;
  userId: string;
  seasons: string[];
  currentSeason?: string;
}) {
  const router = useRouter();
  const [season, setSeason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleRenew() {
    if (!season) return;
    setSubmitting(true);
    setError(null);

    try {
      const res = await fetch(
        `/api/v1/t/${tenantSlug}/members/${userId}/renew`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ season }),
        }
      );

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error ?? "Failed to renew");
      }

      if (data.attestationSent) {
        setSeason("");
      }

      router.refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="flex items-end gap-2">
      <div className="flex-1">
        <Select value={season} onValueChange={(v) => setSeason(v ?? "")}>
          <SelectTrigger>
            <SelectValue placeholder="Select season..." />
          </SelectTrigger>
          <SelectContent>
            {seasons.map((s) => (
              <SelectItem key={s} value={s} label={s} disabled={s === currentSeason}>
                {s} {s === currentSeason ? "(current)" : ""}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <Button
        size="sm"
        onClick={handleRenew}
        disabled={submitting || !season}
      >
        {submitting ? "..." : "Renew"}
      </Button>
      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}
