CREATE UNIQUE INDEX IF NOT EXISTS "attestation_requests_one_pending_renewal"
  ON "attestation_requests" ("tenant_id", "user_id", "season")
  WHERE "status" = 'pending' AND "credential_ids" IS NULL;
EOF
