import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { and, eq, inArray } from "drizzle-orm";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { NextRequest } from "next/server";

/**
 * A member has at most one pending renewal attestation per season.
 *
 * Nov 2026: Renew inserted a new pending attestation on every call, and the
 * member page Re-send called Renew, so a repeated click or a re-send left the
 * member listed twice on the admin Requests page with two live links
 * (production request log: three members with two 200 Renew calls 4 to 6
 * seconds apart in twelve days).
 *
 * Proves:
 *   (a) the first Renew creates one pending attestation and sends one email,
 *   (b) a second Renew moments later keeps that one row, keeps its link and
 *       sends no second email,
 *   (c) a Renew after the repeat-click window re-issues the link on the same
 *       row and emails the member again,
 *   (d) the database refuses a second pending renewal row for the same
 *       member and season (migration 0022),
 *   (e) a scoped fob confirmation may sit beside the renewal attestation,
 *   (f) once the attestation is no longer pending, Renew starts a new one,
 *   (g) the member page Re-send no longer goes through Renew.
 *
 * Auth, tenant and permissions are mocked so the handler runs directly;
 * everything below it hits the real database. Gated on DATABASE_URL.
 */

const hasDb = !!process.env.DATABASE_URL;

const ctx: { tenant: { id: string; slug: string } | null; actorId: string | null } = {
  tenant: null,
  actorId: null,
};

const sentTemplates: string[] = [];

vi.mock("@/lib/auth", () => ({
  getAuthUser: async () => ({
    user: {
      id: ctx.actorId,
      firebaseUid: "renew-once-fb",
      email: "renew-once@example.com",
      firstName: "Renew",
      lastName: "Admin",
      phone: null,
    },
    memberships: [],
    isGlobalAdmin: false,
  }),
}));

vi.mock("@/lib/tenant", () => ({
  resolveTenant: async (slug: string) =>
    ctx.tenant && slug === ctx.tenant.slug
      ? {
          id: ctx.tenant.id,
          name: "Renew Once Club",
          slug: ctx.tenant.slug,
          settings: {},
          timezone: "Australia/Melbourne",
          logoUrl: null,
          stripeAccountId: null,
        }
      : null,
}));

vi.mock("@/lib/permissions", () => ({
  checkPermission: () => ({ granted: true }),
  checkMembership: () => ({ granted: true }),
}));

vi.mock("@/lib/services/email", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/services/email")>();
  return {
    ...actual,
    sendTemplatedEmail: vi.fn(async (_to: string, template: string) => {
      sentTemplates.push(template);
      return { sent: true } as never;
    }),
    sendEmail: vi.fn(async () => ({ sent: true }) as never),
  };
});

const SEASON = "2026/2027";

describe("member page Re-send wiring", () => {
  it("re-issues the pending attestation in place instead of calling Renew", () => {
    const section = readFileSync(
      resolve(__dirname, "../app/t/[slug]/admin/members/[id]/attestation-section.tsx"),
      "utf8"
    );
    const handleResend = section.slice(
      section.indexOf("async function handleResend"),
      section.indexOf("if (attestations.length === 0")
    );
    expect(handleResend).toContain("/resend-attestation");
    expect(handleResend).toContain("attestationId: pending.id");
    expect(handleResend).not.toContain("/renew`");
  });
});

describe.skipIf(!hasDb)("renew keeps one pending attestation per member and season", () => {
  let db: typeof import("@accessbuddy/db").db;
  let tenants: typeof import("@accessbuddy/db").tenants;
  let users: typeof import("@accessbuddy/db").users;
  let tenantMemberships: typeof import("@accessbuddy/db").tenantMemberships;
  let attestationRequests: typeof import("@accessbuddy/db").attestationRequests;
  let auditLog: typeof import("@accessbuddy/db").auditLog;
  let renew: typeof import("@/app/api/v1/t/[slug]/members/[id]/renew/route").POST;

  let tenant: { id: string; slug: string };
  let admin: { id: string };
  let member: { id: string };
  let suffix: string;

  async function post(season = SEASON) {
    const request = new NextRequest(
      `http://localhost/api/v1/t/${tenant.slug}/members/${member.id}/renew`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ season }),
      }
    );
    const res = await renew(request, {
      params: Promise.resolve({ slug: tenant.slug, id: member.id }),
    });
    return { status: res.status, json: await res.json() };
  }

  async function rows() {
    return db
      .select()
      .from(attestationRequests)
      .where(
        and(eq(attestationRequests.tenantId, tenant.id), eq(attestationRequests.userId, member.id))
      );
  }

  async function renewAudits() {
    const all = await db
      .select({ metadata: auditLog.metadata })
      .from(auditLog)
      .where(and(eq(auditLog.tenantId, tenant.id), eq(auditLog.entityId, member.id)));
    return all.filter((r) => (r.metadata as Record<string, unknown> | null)?.action === "renew");
  }

  /** Move the pending row out of the repeat-click window. */
  async function age(id: string) {
    await db
      .update(attestationRequests)
      .set({ updatedAt: new Date(Date.now() - 5 * 60_000) })
      .where(eq(attestationRequests.id, id));
  }

  beforeAll(async () => {
    const dbPackage = await import("@accessbuddy/db");
    db = dbPackage.db;
    tenants = dbPackage.tenants;
    users = dbPackage.users;
    tenantMemberships = dbPackage.tenantMemberships;
    attestationRequests = dbPackage.attestationRequests;
    auditLog = dbPackage.auditLog;

    suffix = `${Date.now()}`;
    const [t] = await db
      .insert(tenants)
      .values({ name: `Renew Once Club ${suffix}`, slug: `renew-once-${suffix}` })
      .returning({ id: tenants.id, slug: tenants.slug });
    tenant = t;
    ctx.tenant = tenant;

    const mkUser = async (tag: string, first: string, last: string) => {
      const [u] = await db
        .insert(users)
        .values({
          firebaseUid: `renew-once-${tag}-${suffix}`,
          email: `renew-once-${tag}-${suffix}@example.com`,
          firstName: first,
          lastName: last,
        })
        .returning({ id: users.id });
      return u;
    };
    admin = await mkUser("admin", "Renew", "Admin");
    member = await mkUser("member", "Mia", "Member");
    ctx.actorId = admin.id;

    await db.insert(tenantMemberships).values({
      tenantId: tenant.id,
      userId: member.id,
      status: "active",
      currentSeason: "2025/2026",
    });

    ({ POST: renew } = await import("@/app/api/v1/t/[slug]/members/[id]/renew/route"));
  });

  beforeEach(async () => {
    sentTemplates.length = 0;
    await db.delete(auditLog).where(eq(auditLog.tenantId, tenant.id));
    await db.delete(attestationRequests).where(eq(attestationRequests.tenantId, tenant.id));
  });

  afterAll(async () => {
    await db.delete(auditLog).where(eq(auditLog.tenantId, tenant.id));
    await db.delete(attestationRequests).where(eq(attestationRequests.tenantId, tenant.id));
    await db.delete(tenantMemberships).where(eq(tenantMemberships.tenantId, tenant.id));
    await db.delete(tenants).where(eq(tenants.id, tenant.id));
    await db.delete(users).where(inArray(users.id, [admin.id, member.id]));
  });

  it("(a) first Renew creates one pending attestation and sends one email", async () => {
    const res = await post();
    expect(res.status).toBe(200);
    expect(res.json).toMatchObject({ attestationSent: true, reused: false, emailed: true });

    const all = await rows();
    expect(all).toHaveLength(1);
    expect(all[0]).toMatchObject({ status: "pending", season: SEASON, credentialIds: null });
    expect(all[0].id).toBe(res.json.attestationId);
    expect(sentTemplates).toEqual(["attestationRequested"]);
    expect(await renewAudits()).toHaveLength(1);
  });

  it("(b) a repeated click keeps the one row and its link and sends nothing more", async () => {
    const first = await post();
    const [before] = await rows();

    const second = await post();
    expect(second.status).toBe(200);
    expect(second.json).toMatchObject({
      attestationSent: true,
      attestationId: first.json.attestationId,
      reused: true,
      emailed: false,
    });

    const all = await rows();
    expect(all).toHaveLength(1);
    expect(all[0].token).toBe(before.token);
    expect(all[0].tokenExpiresAt.getTime()).toBe(before.tokenExpiresAt.getTime());
    expect(sentTemplates).toEqual(["attestationRequested"]);
    expect(await renewAudits()).toHaveLength(1);
  });

  it("(c) a later Renew re-issues the link on the same row and emails again", async () => {
    const first = await post();
    const [before] = await rows();
    await age(before.id);

    const later = await post();
    expect(later.json).toMatchObject({
      attestationId: first.json.attestationId,
      reused: true,
      emailed: true,
    });

    const all = await rows();
    expect(all).toHaveLength(1);
    expect(all[0].id).toBe(before.id);
    expect(all[0].status).toBe("pending");
    expect(all[0].token).not.toBe(before.token);
    expect(all[0].tokenExpiresAt.getTime()).toBeGreaterThanOrEqual(before.tokenExpiresAt.getTime());
    expect(sentTemplates).toEqual(["attestationRequested", "attestationRequested"]);

    const audits = await renewAudits();
    expect(audits).toHaveLength(2);
    expect(
      audits.filter((a) => (a.metadata as Record<string, unknown>).reissued === true)
    ).toHaveLength(1);
  });

  it("(d) the database refuses a second pending renewal for the same member and season", async () => {
    await post();
    await expect(
      db.insert(attestationRequests).values({
        tenantId: tenant.id,
        userId: member.id,
        season: SEASON,
        token: `renew-once-dup-${suffix}`,
        tokenExpiresAt: new Date(Date.now() + 86_400_000),
        status: "pending",
        initiatedBy: admin.id,
      })
    ).rejects.toThrow();
    expect(await rows()).toHaveLength(1);
  });

  it("(e) a scoped fob confirmation may sit beside the renewal attestation", async () => {
    await post();
    await db.insert(attestationRequests).values({
      tenantId: tenant.id,
      userId: member.id,
      season: SEASON,
      token: `renew-once-scoped-${suffix}`,
      tokenExpiresAt: new Date(Date.now() + 86_400_000),
      status: "pending",
      initiatedBy: admin.id,
      credentialIds: ["00000000-0000-4000-8000-000000000001"],
    });
    const [renewal] = (await rows()).filter((r) => !r.credentialIds?.length);
    await age(renewal.id);

    // Renew re-issues the renewal attestation and leaves the scoped one alone.
    const again = await post();
    expect(again.json.attestationId).toBe(renewal.id);

    const all = await rows();
    expect(all).toHaveLength(2);
    const scoped = all.find((r) => r.credentialIds?.length);
    expect(scoped).toMatchObject({ status: "pending", token: `renew-once-scoped-${suffix}` });
  });

  it("(f) once the attestation is no longer pending, Renew starts a new one", async () => {
    const first = await post();
    await db
      .update(attestationRequests)
      .set({ status: "completed", completedAt: new Date() })
      .where(eq(attestationRequests.id, first.json.attestationId));

    const next = await post();
    expect(next.json).toMatchObject({ reused: false, emailed: true });
    expect(next.json.attestationId).not.toBe(first.json.attestationId);

    const all = await rows();
    expect(all).toHaveLength(2);
    expect(all.filter((r) => r.status === "pending")).toHaveLength(1);
  });
});
EOF
